class Solution {
public:
    vector<string> cellsInRange(string s) {
        vector<string> res;
        for (char c = s[0]; c <= s[3]; c++) {
            for (char r = s[1]; r <= s[4]; r++) {
                res.push_back(string(1, c) + r);
            }
        }
        return res;
    }
};

class Solution {
    public List<String> cellsInRange(String s) {
        List<String> res = new ArrayList<>();
        for (char c = s.charAt(0); c <= s.charAt(3); c++) {
            for (char r = s.charAt(1); r <= s.charAt(4); r++) {
                res.add("" + c + r);
            }
        }
        return res;
    }
}

/**
 * @param {string} s
 * @return {string[]}
 */
var cellsInRange = function(s) {
    const res = [];
    const c1 = s.charCodeAt(0), r1 = parseInt(s[1], 10);
    const c2 = s.charCodeAt(3), r2 = parseInt(s[4], 10);
    for (let c = c1; c <= c2; c++) {
        for (let r = r1; r <= r2; r++) {
            res.push(String.fromCharCode(c) + r);
        }
    }
    return res;
};
